<template>
	<view class="pages">
		<view class="headerClass">
			<view class="header-item">
				<uni-data-select :localdata="[
					{
						text: '话务员',
						value: 1
					},
					{
						text: '业务员',
						value: 2
					},
					{
						text: '微信号',
						value: 3
					},
					{
						text: '任务分组',
						value: 4
					}
				]" :clear="false" v-model="roleType" @change="initTotalData"></uni-data-select>
			</view>
			<view class="header-item">
				<uni-datetime-picker type="daterange" v-model="timeArray" :start="startTime" :end="endTime" @change="initData">{{ timeArray.length > 0 ? timeArray[0].substring(5) + '—' + timeArray[1].substring(5) : '选择日期' }}</uni-datetime-picker>
			</view>
			<view class="header-item">
				<uni-data-select :localdata="[
					{
						text: '在岗列表',
						value: 1
					},
					{
						text: '与我相关',
						value: 2
					},
					{
						text: '分组展示',
						value: 3
					}
				]" :clear="false" v-model="listType" @change="initTotalData"></uni-data-select>
			</view>
		</view>
		<mescroll-body ref="mescroll" @down="downCallback" :up="{ use: false }">
			<view class="contentClass">
				<view class="table">
					<view class="table-header">
						<view @click="checkAll()" class="header-item">
							<view class="text">明细</view>
						</view>
						<view class="header-item">{{ '邀请 ' + total }}</view>
						<!-- <view class="header-item">{{roleType==3?'微信号':roleType==2?'业务员':'话务员'}}</view> -->
						<view class="header-item">{{ '新增 ' + total }}</view>
						<!-- <view class="header-item">合计</view> -->
					</view>
					<view v-if="dataList && dataList.length > 0" class="table-todoy">
						<view :class="item.isOneself ? 'todoy-line todoy-line-oneself' : 'todoy-line'" v-for="(item, index) in dataList" :key="index" @click="checkDetail(item)">
							<view class="header-item line-name">
								<view class="name-text">{{ item.name }}</view>
								<image v-if="[1, 2, 3].includes(item.rank)" :src="'/static/' + (item.rank == 1 ? 'first' : (item.rank == 2 ? 'second' : 'third')) + '.png'" class="rank-img" mode="scaleToFill" />
							</view>
							<view class="header-item">{{ item.num }}</view>
							<view class="header-item item-num">
								<view>{{ item.num }}</view>
								<image src="/static/right.png" class="right-img" mode="widthFix"></image>
							</view>
						</view>
					</view>
					<view v-if="dataList && dataList.length == 0" class="none-data">
						<noData />
					</view>
				</view>
			</view>
		</mescroll-body>
		<uni-popup ref="popup" type="bottom">
			<view class="popup-content">
				<view @click="remoDetail" class="popup-line">查看明细</view>
				<view @click="remoTask" class="popup-line">查看相关任务</view>
				<view @click="close" class="popup-close">取消</view>
			</view>
		</uni-popup>
		<tab :id="2"/>
	</view>
</template>

<script>
import {
	getTotalData
} from '@/util/api';
import noData from '../component/noData.vue'
import tab from "../../components/wyg-bottom-tab/wyg-bottom-tab.vue";

export default {
	components: { noData, tab },
	data() {
		return {
			roleType: 1,
			timeArray: [],
			listType: 1,
			dataList: [],
			total: '',
			detail: {},
			startTime: new Date('2020-01-01').getTime(),
			endTime: new Date()
		}
	},
	methods: {
		async downCallback(mescroll) {
			this.initDate()
			await this.initTotalData()
			mescroll.endSuccess()
		},
		initDate() {
			const today = new Date();
			const year = today.getFullYear();
			const month = today.getMonth() + 1;  // 月份从0开始，所以要加1
			const day = today.getDate();
			const time = year + '-' + month + '-' + day
			this.timeArray = [time, time]
		},
		checkDetail(item) {
			let userInfo = uni.getStorageSync('userInfo')
			if (['a', 'c', 'd'].includes(userInfo.userRole) || item.isOneself) {
				this.detail = item
				this.$refs.popup.open()
			} else {
				return uni.showToast({
					title: '您没有权限查看',
					icon: 'none',
					mask: true
				})
			}
		},
		initData(e) {
			this.timeArray = e
			this.initTotalData()
		},
		async initTotalData() {
			const _this = this
			let params = {
				roleType: this.roleType,
				listType: this.listType
			}
			if (this.timeArray.length > 1) {
				params.startTime = this.timeArray[0]
				params.endTime = this.timeArray[1]
			}
			await getTotalData(params).then(res => {
				const dataList = res.data
				_this.total = 0
				dataList.sort((a, b) => {
					if (a.num > b.num) return -1; // a应该排在b前面
					if (a.num < b.num) return 1;  // a应该排在b后面
					return 0; // 如果相同，保持原顺序
				});

				let rank = 0;
				let prevScore = null;
				const userInfo = uni.getStorageSync('userInfo')
				dataList.forEach((player, index) => {
					_this.total += player.num
					if (prevScore !== player.num) {
						rank++; // 新的排名始于当前索引加1
					}
					if (userInfo?.userInfo?.id == player.userId) {
						player.isOneself = true
					}
					player.rank = rank; // 添加排名属性到每个对象中
					prevScore = player.num; // 更新prevScore为当前玩家的分数，用于下一次比较
				});
				this.dataList = dataList
				console.log(this.dataList, 'this.dataList');
			})
		},
		remoDetail() {
			const _this = this
			uni.navigateTo({
				url: './detail?userId=' + _this.detail.userId || ''
			})
			this.close()
		},
		remoTask() {
			uni.navigateTo({
				url: './taskDetail?userId=' + this.detail?.userId + '&roleType=' + this.roleType
			})
			this.close()
		},
		close() {
			this.$refs.popup.close()
		},
		remove() {
			removeDetailInfo({ id: this.detail.id }).then(res => {
				uni.showToast({
					title: '删除成功',
					icon: 'none',
					mask: true
				})
			})
		},
		checkAll() {
			let userInfo = uni.getStorageSync('userInfo');
			uni.navigateTo({
				url: './detail?userId=' + userInfo?.userInfo?.id || ''
			})
		}
	}
}
</script>

<style lang="scss" scoped>
.headerClass {
	display: flex;
	align-items: center;
	justify-content: space-between;
	margin: 14rpx 18rpx;

	.header-item {
		font-size: 28rpx;
	}
}

.contentClass {
	.table {
		.table-header {
			display: flex;
			padding: 12rpx 24rpx 12rpx 42rpx;
			background: #ebebeb;

			.header-item {
				width: 33.33%;
				font-size: 28rpx;
				margin: auto 0;

				.text {
					width: 60rpx;
					background: white;
					padding: 12rpx 20rpx;

				}

				&:first-child {}

				&:nth-child(2) {
					text-align: center;
				}

				&:nth-child(3) {
					text-align: right;
				}
			}
		}

		.table-todoy {

			.todoy-line {
				display: flex;
				padding: 0 24rpx 0 12rpx;
				border-bottom: 2rpx solid #eee;

				.line-name {
					display: flex;
					align-items: center;

					.name-text {
						white-space: nowrap;
						background: white;
						padding: 12rpx 12rpx 12rpx 20rpx;
					}

					.rank-img {
						width: 40rpx;
						height: 40rpx;
						display: flex;
					}
				}

				.item-num {
					display: flex;
					justify-content: flex-end;
				}

				.header-item {
					width: 33.33%;
					font-size: 28rpx;
					margin: auto 0;

					.right-img {
						width: 24rpx;
						height: 24rpx;
						margin: auto 8rpx;
					}

					&:first-child {
						padding: 12rpx 20rpx;
						background: white;
					}

					&:nth-child(2) {
						text-align: center;
					}

					&:nth-child(3) {
						text-align: right;
					}
				}
			}
			.todoy-line-oneself{
				color: red;
			}
		}

		.none-data {
			font-size: 36rpx;
			color: #656565;
			padding: 200rpx 0 0 0;
			text-align: center;
		}
	}
}

.popup-content {
	background: white;
	padding: 24rpx 0 12rpx 0;
	border-radius: 20rpx 20rpx 0 0;

	.title {
		font-size: 36rpx;
		font-weight: 500;
		text-align: center;
		padding: 0 0 12rpx 0;
	}

	.popup-line {
		padding: 12rpx 0;
		text-align: center;
		font-size: 36rpx;
	}

	.popup-close {
		color: #807d7d;
		padding: 24rpx 0 16rpx 0;
		font-size: 30rpx;
		text-align: center;
	}

}

::v-deep .uni-select__selector-item {
	white-space: nowrap;
}
</style>